DROP TABLE IF EXISTS `flight_schedules`;
CREATE TABLE `flight_schedules` (
  `id` char(36) NOT NULL,
  `flight_number` varchar(10) NOT NULL,
  `route_id` bigint(20) unsigned NOT NULL,
  `model_id` bigint(20) unsigned NOT NULL,
  `departure_time_utc` time NOT NULL,
  `arrival_time_utc` time NOT NULL,
  `days_of_week` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`days_of_week`)),
  `status` varchar(20) NOT NULL DEFAULT 'PUBLISHED',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `aircraft_tail` varchar(20) DEFAULT NULL,
  `resource_id` bigint(20) unsigned DEFAULT NULL,
  `effective_from` date DEFAULT NULL,
  `effective_to` date DEFAULT NULL,
  `version` int(10) unsigned NOT NULL DEFAULT 0,
  `validation_notes` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `flight_schedules_model_id_foreign` (`model_id`),
  KEY `flight_schedules_flight_number_is_active_index` (`flight_number`,`is_active`),
  KEY `flight_schedules_route_id_index` (`route_id`),
  KEY `flight_schedules_status_index` (`status`),
  KEY `flight_schedules_aircraft_tail_foreign` (`aircraft_tail`),
  KEY `flight_schedules_resource_id_foreign` (`resource_id`),
  CONSTRAINT `flight_schedules_aircraft_tail_foreign` FOREIGN KEY (`aircraft_tail`) REFERENCES `aircrafts` (`tail_number`),
  CONSTRAINT `flight_schedules_model_id_foreign` FOREIGN KEY (`model_id`) REFERENCES `aircraft_models` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `flight_schedules_resource_id_foreign` FOREIGN KEY (`resource_id`) REFERENCES `airport_resources` (`id`),
  CONSTRAINT `flight_schedules_route_id_foreign` FOREIGN KEY (`route_id`) REFERENCES `routes` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
