DROP TABLE IF EXISTS `operational_flights`;
CREATE TABLE `operational_flights` (
  `id` char(36) NOT NULL,
  `schedule_id` char(36) DEFAULT NULL,
  `flight_number` varchar(10) NOT NULL,
  `flight_date` date NOT NULL,
  `route_id` bigint(20) unsigned NOT NULL,
  `aircraft_tail` varchar(20) NOT NULL,
  `scheduled_dep_utc` datetime NOT NULL,
  `scheduled_arr_utc` datetime NOT NULL,
  `actual_dep_utc` datetime DEFAULT NULL,
  `actual_arr_utc` datetime DEFAULT NULL,
  `flight_status` varchar(20) NOT NULL DEFAULT 'SCHEDULED',
  `gate_number` varchar(20) DEFAULT NULL,
  `delay_reason` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `resource_id` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_flight_number_per_date` (`flight_number`,`flight_date`),
  KEY `operational_flights_schedule_id_foreign` (`schedule_id`),
  KEY `idx_aircraft_departure` (`aircraft_tail`,`scheduled_dep_utc`),
  KEY `idx_aircraft_arrival` (`aircraft_tail`,`scheduled_arr_utc`),
  KEY `idx_route_flight_date` (`route_id`,`flight_date`),
  KEY `operational_flights_flight_status_index` (`flight_status`),
  KEY `operational_flights_resource_id_foreign` (`resource_id`),
  CONSTRAINT `operational_flights_aircraft_tail_foreign` FOREIGN KEY (`aircraft_tail`) REFERENCES `aircrafts` (`tail_number`) ON UPDATE CASCADE,
  CONSTRAINT `operational_flights_resource_id_foreign` FOREIGN KEY (`resource_id`) REFERENCES `airport_resources` (`id`),
  CONSTRAINT `operational_flights_route_id_foreign` FOREIGN KEY (`route_id`) REFERENCES `routes` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `operational_flights_schedule_id_foreign` FOREIGN KEY (`schedule_id`) REFERENCES `flight_schedules` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
