DROP TABLE IF EXISTS `crew_members`;
CREATE TABLE `crew_members` (
  `id` char(36) NOT NULL,
  `crew_code` varchar(20) NOT NULL,
  `full_name` varchar(100) NOT NULL,
  `email` varchar(100) NOT NULL,
  `phone` varchar(20) NOT NULL,
  `rank` varchar(30) NOT NULL,
  `base_airport_code` varchar(3) NOT NULL,
  `license_number` varchar(50) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'AVAILABLE',
  `total_flight_hours` decimal(10,2) NOT NULL DEFAULT 0.00,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `license_expires_on` date DEFAULT NULL,
  `training_expires_on` date DEFAULT NULL,
  `qualified_model_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`qualified_model_ids`)),
  `available_from_utc` datetime DEFAULT NULL,
  `available_until_utc` datetime DEFAULT NULL,
  `user_id` char(36) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `crew_members_crew_code_unique` (`crew_code`),
  UNIQUE KEY `crew_members_email_unique` (`email`),
  UNIQUE KEY `crew_members_license_number_unique` (`license_number`),
  KEY `crew_members_rank_index` (`rank`),
  KEY `crew_members_status_index` (`status`),
  KEY `crew_members_base_airport_code_index` (`base_airport_code`),
  KEY `crew_members_user_id_index` (`user_id`),
  CONSTRAINT `crew_members_base_airport_code_foreign` FOREIGN KEY (`base_airport_code`) REFERENCES `airports` (`iata_code`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
